export default defineEventHandler(async (event) =>
{

  const params = [];
  for(const file of files)
  {
//    const arr = await csv().fromFile(file);
    const arr = await csv().fromString(file);
    params.push(...arr);
  }

  return JSON.stringify(params);
})


